  i.ITEMID AS MATERIAL, l.MEMO AS ITEM_TEXT, l.CLASS AS MATERIAL_GROUP, l.QUANTITY, NULL::STRING AS UOM, l.RATE AS NET_PRICE,
  l.FOREIGNAMOUNT AS NET_VALUE, t.CURRENCY, t.TRANDATE AS PO_DATE, NULL::DATE AS DELIVERY_DATE, NULL::STRING AS CONTRACT_ID
FROM {{ source('src_netsuite', 'transactionline') }} l JOIN {{ source('src_netsuite', 'transaction') }} t ON t.ID = l.TRANSACTION LEFT JOIN {{ source('src_netsuite', 'item') }} i ON i.ID = l.ITEM WHERE t.TYPE = 'PurchOrd'
